package com.zenbyte.leave.controller;
import com.zenbyte.leave.dto.EmployeeRequest; import com.zenbyte.leave.entity.Employee; import com.zenbyte.leave.service.EmployeeService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/employees") public class EmployeeController {private final EmployeeService s; public EmployeeController(EmployeeService s){this.s=s;} @GetMapping public List<Employee> list(@RequestParam(required=false) String search){return s.list(search);} @GetMapping("/{id}") public Employee get(@PathVariable Long id){return s.get(id);} @PostMapping public Employee create(@Valid @RequestBody EmployeeRequest r){return s.create(r);} @PutMapping("/{id}") public Employee update(@PathVariable Long id,@Valid @RequestBody EmployeeRequest r){return s.update(id,r);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);} }
